from datetime import datetimeimport osfrom functools import wrapsif not os.path.exists('logs'):    os.mkdir('logs')SESSION_TIME = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")LOG_FILE_PATH = os.path.join('logs', f'session_{SESSION_TIME}.txt')def log_action(func):    @wraps(func)    def wrapper(*args, **kwargs):        action_time = datetime.now().strftime('%H:%M:%S')        with open(LOG_FILE_PATH, 'a', encoding='utf-8') as log_file:            log_file.write(f"[{action_time}] ЗАПУСК функции: {func.__name__}\n")            if len(args) > 1 or kwargs:                log_file.write(f"    Параметры поиска: args={args[1:]}, kwargs={kwargs}\n") # [1:] убираем self        try:            result = func(*args, **kwargs)            with open(LOG_FILE_PATH, 'a', encoding='utf-8') as log_file:                log_file.write(f"[{datetime.now().strftime('%H:%M:%S')}] УСПЕХ: {func.__name__} выполнен без ошибок\n")            return result        except Exception as e:            with open(LOG_FILE_PATH, 'a', encoding='utf-8') as log_file:                log_file.write(f"[{datetime.now().strftime('%H:%M:%S')}] ОШИБКА в {func.__name__}: {e}\n")            raise e    return wrapperdef format_output(title):    def decorator_format_output(func):        @wraps(func)        def wrapper(*args, **kwargs):            print(f"\n{'=' * 10} {title.upper()} {'=' * 10}")            result = func(*args, **kwargs)            print(result)            print("=" * (22 + len(title)))            return result        return wrapper    return decorator_format_output